#!/bin/zsh
# juniorstock/build/compile_kernels.sh
# Executes the Cython build and purges original .py artifacts

echo "[BUILD GATE] Initiating Cython compilation..."
cd "$(dirname "$0")"

# Execute build in place
python3 setup.py build_ext --inplace

echo "[BUILD GATE] Compilation successful. Purging symbolic artifacts..."

# Remove intermediate C files generated by Cython
find .. -name "*.c" -type f -delete

# Purge original Python files for the compiled targets to enforce Black Box
rm -f ../math/fsd/kinematics.py
rm -f ../quant/atml_core.py
rm -f ../blackbox/strategy_container.py
rm -f ../risk/topo_allocator.py

# Remove PyCache bloat
find .. -name "__pycache__" -type d -exec rm -rf {} +

echo "[BUILD GATE] Sovereign kernels locked. .so binaries active."
